/** A coin as the BNR describes it; the facts it has no field for stay in its words. */
export type BnrCoin = {
  /** The Catalog id. */
  key: string;
  title: string;
  denomination: string;
  year: number;
  /** YYYY-MM-DD */
  issueDate?: string;
  material?: string;
  metal?: string;
  fineness?: number;
  weight?: number;
  diameter?: number;
  thickness?: number;
  composition?: string;
  edge?: string;
  strike?: string;
  /** The BNR's description, in Romanian. */
  details: string;
  /** The BNR's page the facts come from. */
  link: string;
};

/** A banknote as the BNR describes it. */
export type BnrBanknote = Pick<
  BnrCoin,
  "key" | "title" | "denomination" | "year" | "issueDate" | "details" | "link"
> & { width?: number; height?: number };

/** An issue of several coins, or a mint set. */
export type BnrIssue = {
  key: string;
  title: string;
  year: number;
  issueDate?: string;
  link: string;
  details?: string;
  pieces: BnrCoin[];
};

